"""Library for Traffic Keywords.

    = Configuration Needed =
    === testline_config ===
    | *"traffic_capture"* :{
    |	"_*capture_device_name1*_": {	User defined capture device name
    | 		*"tool"* : "",	            Tool for capturing. Possible values:
    |                                   tshark, tcpdump, oam_tool
    | 		*"ip"* : "",	            IP address of the remote machine to
    |                                   capture
    | 		*"user"* : "",	            Username of the remote machine for
    |                                   login for ssh login
    | 		*"password"* : "",	        Password of the remote machine for
    |                                   login for ssh login
    | 		*"capture_port"* : "",	    Port used for ssh login
    | 		*"capture_interface"* : "",	Interface on the remote machine to
    |                                   capture
    | 		*"ssh_prompt"* : "",	        ssh prompt for ssh login
    |           *"config_name"* : "",     Section name in config to read connection detail
    |           *"log_dir"* : "",     path to store the pcap on remote device
    |           *"tcpdump_dir"* : "",     path of tcpdump binary
    |           *"fhnet_cap_only"* : "",     True if capture is on fhnet
    |           *"hop_list"* : "",     list of hop connections to be made
    | 	},
    | }

    | *"generators"* :{
    |	_*"generator_name1"*_: {	    User defined generator name
    | 		*"tool"* : "",              Tool for generating traffic. Possible
    |                                   values: scapy
    | 		*"ip"* : "",                IP address of the remote machine
    |                                   running traffic generator
    |		*"user"* : "",		        IP address of the remote machine
    |                                   running traffic generator
    | 		*"password"* : "",          Password of the remote machine for
    |                                   login for ssh login
    | 		*"interface"* : "",         Ethernet interface/List of interfaces for sending traffic
    | 		*"prompt"* : "",            ssh prompt for ssh login
    |       *"server_bin_path"* : "",   Path of server binary from the traffic generator installation directory
    |       *"env"* : {
    |           *"PYTHONPATH"*: "",     Path of Trex Client Library from the traffic generator installation directory
    |       },
    | 	},
    | }


    | *"impairments"* :{
    |	*"netem"*: {
    | 		*"ip"* : "",        IP address of the remote machine running
    |                           generating impairments
    | 		*"user"* : "",	    Username of the remote machine for login for
    |                           ssh login
    | 		*"password"* : ""	Password of the remote machine for login for
    |                           ssh login
    | 	},
    | }


    === testcase_variables ===
    | *"traffic_profiles"* : {
    |	*"profile_name1"*: {          User defined profile name
    | 		*"ip_version"*: "",       IP header version. Values: ipv6 or ipv4
    | 		*"protocol"*: "",         Protocol to be generated. Values:
    |		*"source"*: "",           Source IP address
    | 		*"destination"*: "",      Destination IP address
    | 		*"type"*: ,               Type for IPv6 header
    | 		*"code"*: ,               Code for IPv6 header
    | 		*"speed"*: ,              Paket Rate to be generated in units of
    |                                 Packets per Second(pps)
    | 		*"packets"*: ,            Number of packets to be generated
    |		*"malformed"*: "",        If malformed packets are to be generated
    |                                 or not. Values: true or false
    |		*"src_port"* : "",        Sourde UDP port
    |		*"dst_port"* : ""         Destination UDP port
    |		*"duration"*:             Duration for generating packets
    |       *"dhcp_options"*:         DHCP Options
    |	},
    | }

    | *"impairments_profile"* : {
    |	_*"profile_name1"*_: {          User defined profile name
    | 		*"dest_ip"*: "",            Destination IP for which impairments
    |                                    need to be generated
    | 		*"ethport"*: "",            Ethernet interface on the remote
    |                                   machine where impairments need to be
    |                                   generated
    | 		*"protocol"*: "",           Protocol for which impairments need to
    |                                   be generated.
    | 		*"percent"*: "",            Percentage of data to be impaired
    | 		*"delay"*: "",              Delay value in units of ms
    |	},
    | }

    === traffic_filters ===
    | *"traffic_analysis"*:{
    |   _*"analysis_name1"*_: {         User defined analysis name
    | 		*"filter"*: "",             Filters to applied on the capture as
    |                                   expected by tshark option -Y. Has to be
    |                                   in tshark filters format
    | 		*"eval"*: "",               Type of analysis. Values: 'count',
    |                                   'getValue'
    |		*"expected_result"*: "1-*", Expected count, Used in case of
    |                                   eval=count
    | 		*"tolerance"*: 0,           Tolerance for the packets count
    | 		*"display_fields"*: "",     Fields to be displayed, as expected by
    |                                   tshark option -e
    | 		*"decode_as"*: ""           tshark decode-as option as expecetd by
    |                                   -d
    |		},
    | }



    = Example =

    | ***** Test Cases *****
    | Sample LTE call
    |     Traffic Setup   device=device_1  alias=traffic_alias
    |     Traffic Capture Start        capture_device=bts    alias=capture_alias
    |     Traffic Start   profile=ipv4_malformed_ports            alias=traffic_alias
    |     Sleep	10
    |     ${filename}=            Traffic Capture Stop             alias=capture_alias
    |     Traffic Teardown        alias=traffic_alias
    |     Traffic Capture Start        capture_device=bts    alias=capture_alias
    |     Analyse Pcap                    ${filename}              lte_attach_request



    == Sample Configuration ==
    | "traffic_analysis":{
    |		"lte_attach_request": {
    |			  "filter": "(ip.src=={lte_cplane1} && ip.dst=={mme} &&
    |                       (nas_eps.nas_msg_emm_type == 0x41))",
    |			  "eval": "count",
    |			  "expected_result": "1-*",
    |			  "tolerance": 0
    |		}

"""
from __future__ import absolute_import, division, print_function,\
    unicode_literals
from future import standard_library
from taf.ul.trs_e2e_fw.lib.traffic.capture.traffic_capture_manager import TrafficCaptureManager
from taf.ul.trs_e2e_fw.lib.traffic.generator.traffic_generator_manager import\
    TrafficGeneratorManager
from taf.ul.trs_e2e_fw.lib.traffic.analysis.analysepcap import AnalysePcap
from taf.ul.trs_e2e_fw.lib.traffic.impairments.impairments import Impairments

standard_library.install_aliases()


def traffic_setup(**kwargs):
    """This keyword is used to setup device for traffic generation. Currently
    Scapy is supported

   | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
   | device | 'device_1' | Details of the device where traffic has to be captured |
        'testline_config' section [generator] |
   | alias | 'default' | Name of the execution context |
   | rat | At least one of the RATs is Mandatory eg. lte/wcdma/gsm etc. | common |

    *Returns:*\n
    None

    *Raises:*\n
    "AttributeError" : If configuration parameters are not found.

    *Examples:* \n

    Setup a device for Traffic generation with default arguments in testline_config.json section
    [generator]
    | Traffic Setup |

    *Configurations Needed :*

    `testline_config` sections:

    "generator"

    """
    return TrafficGeneratorManager().traffic_setup(**kwargs)


def traffic_start(**kwargs):
    """This keyword is used to start using the device mentioned at `Traffic Setup`. Refer to
        testline testcase config for profile parameters.


   | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
   | profile | 'set1' | Details of the Traffic to be sent | 'testcase_variables' section [traffic_profiles] |
   | alias | 'default' | Name of the execution context |
   | rat | lte/wcdma/gsm | At least one of the RATs is Mandatory.| `testline_config` |

    *Returns:*\n
    tuple : (speed, duration)

    *Raises:*\n

    "Profile (traffic profile) not found in config file." : If given traffic profile name is not present in
        'traffic_profiles' section on config file.
    SSHLibrary exceptions : If making connection to scapy PC failed or if the connection is lost. Or if there are
        failures at tcpdump processing.

    *Examples:*

    Generate ICMP IPV4 packets
    | Traffic Start | profile=icmp_ipv4 |

    *Configurations Needed :*

    `testcase_variables` sections:

    "traffic_profiles"

    """
    return TrafficGeneratorManager().traffic_start(**kwargs)


def traffic_stop(**kwargs):
    """This keyword is used to stop for the given alias.

   | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
   | alias | 'alias' | Name of the execution context |  |
   | rat | lte/wcdma/gsm | At least one of the RATs is Mandatory.| `testline_config` |

    *Returns:*\n
    None

    *Raises:*\n
    None

    *Examples:*

    *Stop traffic for default alias*
    | Traffic stop |
    """
    return TrafficGeneratorManager().traffic_stop(**kwargs)


def traffic_teardown(**kwargs):
    """This keyword is used to teardown and release the resources for the given alias.

   | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
   | alias | 'default' |  Name of the execution context |  |

    *Returns:*\n
    None

    *Raises:*\n
    SSHLibrary exceptions : If teardown was unsuccessful because the connection to the ssh session is lost.


    *Examples:*

    Traffic Teardown for default alias
    | Traffic Teardown |
    """
    return TrafficGeneratorManager().traffic_teardown(**kwargs)


def traffic_capture_start(**kwargs):
    """This keyword is used to start capturing traffic on given capture device.
     Refer to Testline config for Capture device params.

    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | capture_device | Mandatory | The device name according to the testline config, section[traffic_capture] | |
    |  |  |  |'testline_config' |
    | capture_filter | '' | The filter to be applied while capturing traffic |  |
    |  |  |  | testcase config, section [traffic_analysis] |
    | mode | 'streaming' |  Used for oam capture. Possible values 'streaming' or 'file' |  |
    | alias | 'default' | Name of the execution context |  |
    | measurement_point | Mandatory for OAM capture | Should be given when using oam_capture with any mode file or |  |
    |  |  | streaming values are  NE_Terminated or Transport_Interface. Mandatory for OAM capture | |
    | uplane_capturing | True | Given with oam_catpture, can take boolean value |  |
    | dst_mac_addr | Mandatory for OAM capture | mac address , given with streaming mode oam_capture only not with |  |
    |  |  | other captures. Mandatory for OAM capture |  |
    | egress_port_dn | Mandatory for OAM capture |  egress_port_dn , should be given with straming mode oam_capture |  |
    |  |  | only not with other captures. Mandatory for OAM capture |  |
    | timeout | 120 |  |  |
    | passowrd | " " | Used with file mode oam_capture only  |  |
    | rat | lte/wcdma/gsm | At least one of the RATs is Mandatory. | `testline_config` |

     *Returns:*\n

     None (Nothing)

     *Raises:*\n
     "SSHLibrary exceptions" : If making connection to scapy PC failed or if the connection is lost. Or if tcpdump
        operations were unsuccessful.

     *Available dhcp_options:*\n
     Please refer "https://github.com/secdev/scapy/blob/master/scapy/layers/dhcp.py" for available dhcp options and
        dhcp message type.
     Refer to the example below:
     "dhcp_options" : {"message-type" : "decline", "requested_addr" : "1.1.1.1"}

    *Examples:*

    | Traffic Capture Start | capture_device=bts |

    *Configurations Needed :*

    `testline_config` sections:

    "traffic_capture"

    """
    return TrafficCaptureManager().traffic_capture_start(**kwargs)


def traffic_capture_stop(**kwargs):
    """This keyword is used to stop capturing traffic for the give alias used at
        `traffic_capture_start`.

    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | mode | streaming' | Used for oam capture. Possible values 'streaming' or 'file' |  |
    | alias | 'default' | Execution context |  |
    | rat | lte/wcdma/gsm | At least one of the RATs is Mandatory.| `testline_config` |
    | timeout | 120 | Used for oam capture |  |

    *Returns:*

    Filename of the captured file

    *Raises:*\n
    SSHLibrary exceptions : If there are failures during tcpdump processing.

    *Examples:*

    Stop Capture for default alias
    | Traffic Capture Stop |

    Stop Capture and return filename
    | ${filename} =	| Traffic Capture Stop |
    """
    return TrafficCaptureManager().traffic_capture_stop(**kwargs)

def traffic_capture_abort(**kwargs):
    """This keyword is used to Abort IP traffic capture generation for the give alias used at
        `traffic_capture_abort`.

    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | alias | 'default' | Execution context |  |
    | timeout | 120 | Used for oam capture |  |

    *Returns:*

    None

    *Examples:*

    Traffic Capture Abort for default alias
    | Traffic Capture Abort |
    """
    return TrafficCaptureManager().traffic_capture_abort(**kwargs)

def upload_traffic_capture_file(**kwargs):
    """This keyword is used to Upload IP traffic capture file for the give alias used at
        `upload_traffic_capture_file`.

    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | alias | 'default' | Execution context |  |
    | local_path | local path used to save ip traffic capture zip file is Mandatory.| `testline_config` |
    | timeout | 120 | Used for oam capture |  |

    *Returns:*

    absolute file path

    *Examples:*

    Upload Traffic Capture File for default alias
    | Upload Traffic Capture File | local_path = '/home/ute' |

    Upload Traffic Capture File and return filename
    | ${filename} =	| Upload Traffic Capture File |
    """
    return TrafficCaptureManager().upload_traffic_capture_file(**kwargs)

def generate_capture_files(**kwargs):
    """This keyword is used to Generate IP traffic capture files
        `generate_capture_files`

    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | password | | Credentials to be used |  |
    | alias | 'default' | Execution context |  |
    | timeout | 120 | Used for oam capture |  |

    *Returns:*

    None

    *Examples:*

    Generate Capture Files for default alias
    | Generate Capture Files | password=xxxx |
    """
    return TrafficCaptureManager().generate_capture_files(**kwargs)

def analyse_pcap(**kwargs):
    """
    This keyword is used to Analyze a given PCAP file and analysis name.

    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | pcap_filename | Mandatory | The pcap file to be analyzed |  |
    | analysis | Mandatory  | Analysis name according to traffic filters config section [traffic_analysis] | |
    |  |  | | `traffic_filters` |
    | file_name | "traffic_filters.json" | File which contains analysis section. | `traffic_filters` |
    | rat | lte/wcdma/gsm | At least one of the RATs is Mandatory.| `testline_config` |
    | admin_alias | None |  |  |
    | variables | "" |  |  |

    *Returns:*
    packet count which is an "int" type


    *Examples:*

    Analyse capture file capture.pcap, for "lte_attach_request" defined in
     traffic filters.json
    | Analyse Pcap | /home/ute/capture.pcap | lte_attach_request |

    *Configurations Needed :*

    `traffic_filters` sections:

    "traffic_analysis"

    *Raises:*
    "Analysis {filter file name} not present in the given traffic" if json file with analysis is absent.

    """
    analyse_obj = AnalysePcap()
    return analyse_obj.analyse_pcap(**kwargs)


def get_throughput_from_pcap(**kwargs):
    """
    This keyword analyses the packet and returns throughput information.


    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | filename | Mandatory |  The pcap file to be analyzed |  |
    | pcap_filter  | Default is Empty string | Filter to be applied on which throughput is calculated |  |
    | data_unit | bytes |  |  |
    | rat | lte/wcdma/gsm | At least one of the RATs is Mandatory.| `testline_config` |

    *Returns:*
    A dictionary with throughput information.

    *Raises:*\n
    None

    *Examples:*

    *To be provided*

    """

    return AnalysePcap().get_throughput(**kwargs)


def traffic_impairments_generate(**kwargs):
    """
    Impairs packets using netem tool.

    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | impairment_device | netem | Device name according to testline_config.json file, section [impairments] |  |
    |  |  |  | 'testline_config' |
    | operation |  | Can be loss or duplication or reorder |  |
    | profile |  |  Profile name according to testcase variables config file, section [impairments_profile] | |
    |  |  |  | 'testcase_variables' |
    | rat | lte/wcdma/gsm | At least one of the RATs is Mandatory.| `testline_config` |

    *Returns:*\n
     None

    *Eceptions raised:*\n
    SSHLibrary exceptions : If connection to impairment device is unsuccessful.
    'If Operation is not provided, commands param in profile should not be empty' : If the user has not passed a
    value for "operation" parameter and there in no information for the same parameter in profile.

    *Examples:*
    | Traffic Impairments Generate | impairment_device=local_setup | operation=duplication | profile=mplane_impairment |

    *Configurations Needed :*

    `testcase_variables` sections:

    "impairments_profile"
    """
    Impairments().traffic_impairments_generate(**kwargs)


def traffic_impairment_stop(**kwargs):
    """
    Stops impairments.

    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | impairment_device | Device name according to testline_config.json file, section [impairments] | netem |
    | profile | Mandatory | Profile name according to config data, for which impairment was |  |
    |         |           | started.|  |
    | rat | lte/wcdma/gsm | At least one of the RATs is Mandatory.| `testline_config` |

    *Returns:*\n
     None

    *Raises:*\n
     SSHLibrary exceptions : If connection to impairment device is unsuccessful.

    *Examples:*

    | Traffic Impairment Stop     | impairment_device=local_setup |  profile=mplane_impairment |
    """
    Impairments().traffic_impairment_stop(**kwargs)


def traffic_capture_and_replay(**kwargs):
    """
      Capture traffic and replay. Can also modify captured packets before replay.
      | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
      | capture_interface | Mandatory | Ethernet interface to capture the packets. Mandatory |  |
      | replay_interface | Mandatory | Ethernet interface to capture the packets. Mandatory |  |
      | capture_filter | '' | capture filter in tcpdump format. Optional. If not given, packets |  |
      |                |    | will be captured without filter |  |
      | num_pkts_to_send | 1 | Number of packets to send. Optional |  |
      | delay | 0 | Number of seconds to wait after capturing the packet before replaying. Optional |  |
      | alias | 'default' | Name of the execution context |  |
      | **kwargs | Modify parameters can be specified in format <Protocol>.<parameter>=<value>. eg UDP.dport=1000 |  |
      | rat | lte/wcdma/gsm | At least one of the RATs is Mandatory.| `testline_config` |

      *Returns:*\n
       None

      *Raises:*\n
       SSHLibrary exceptions : If making connection to scapy PC failed or if the connection is lost.


      *Examples:*

      | Traffic Capture and Replay  |  |  |
      """

    TrafficGeneratorManager().traffic_capture_and_replay(**kwargs)
